#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# ──────────────────────────────────────────────────────────────────────────
#
# Human-only setup for branded account email (#341): Supabase Auth sends its
# six emails through Resend SMTP from a PRISM address, with the templates in
# docs/email-templates/ (built by scripts/build-email-templates.mjs). The
# Resend key goes straight from the Resend tab into Supabase's SMTP form;
# nothing is written locally.

ROOT_DOMAIN="prismmtg.com"
TEMPLATE_DIR="$(cd "$(dirname "$0")/.." && pwd)/docs/email-templates"
PROD_REF="clqxysoimlsjfmnjbxsa"
TOTAL_STAGES=7

dns() {
  if command -v dig >/dev/null 2>&1; then
    dig +short "$1" "$2"
  else
    curl -s -H 'accept: application/dns-json' \
      "https://cloudflare-dns.com/dns-query?name=$1&type=$2" \
      | grep -o '"data":"[^}]*' | sed 's/^"data":"//; s/"$//; s/\\"/"/g'
  fi
}

# copy_file PATH — put a template on the clipboard when a clipboard tool exists.
copy_file() {
  if command -v wl-copy >/dev/null 2>&1; then wl-copy < "$1"
  elif command -v xclip >/dev/null 2>&1; then xclip -selection clipboard < "$1"
  elif command -v pbcopy >/dev/null 2>&1; then pbcopy < "$1"
  else return 1; fi
}

# paste_template "Supabase tab name" FILE "Subject" — one template, one pause.
paste_template() {
  say ""
  say "${BOLD}$1${RESET}"
  step "Subject: ${BOLD}$3${RESET}"
  if copy_file "${TEMPLATE_DIR}/$2"; then
    step "Body: the HTML is on your clipboard (${2}). Select all in the body editor, paste."
  else
    step "Body: open ${BOLD}${TEMPLATE_DIR}/$2${RESET}, copy all of it, paste into the body editor."
  fi
  step "Save changes."
  pause "Press Enter once \"$1\" is saved."
}

banner "PRISM · Branded account email: Resend SMTP + templates → Supabase (#341)"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Pick the sender"
say "Account email belongs on the root domain, which Resend already sends for"
say "(send.${ROOT_DOMAIN} is its return path). ${BOLD}relay.${ROOT_DOMAIN}${RESET} carries strangers'"
say "commission messages, so keep account email off it."
if [[ -n "$(dns "resend._domainkey.${ROOT_DOMAIN}" TXT || true)" ]]; then
  printf '  %s✓%s %s has a Resend DKIM record.\n' "$GREEN" "$RESET" "$ROOT_DOMAIN"
else
  warn "${ROOT_DOMAIN} has no Resend DKIM record. Add and verify it at resend.com/domains first."
  SKIPPED+=("Verify ${ROOT_DOMAIN} in Resend")
fi
ask SENDER "Sender address [accounts@${ROOT_DOMAIN}]:"
SENDER="${SENDER:-accounts@${ROOT_DOMAIN}}"
pause

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Resend — an SMTP key for Supabase"
open_url "https://resend.com/api-keys"
step "Create API key → Name: ${BOLD}prism-supabase-auth${RESET}"
step "Permission: ${BOLD}Sending access${RESET} → Domain: ${BOLD}${SENDER#*@}${RESET}."
step "Add → copy the key (re_…). Resend shows it once; it goes straight into Supabase next."
pause

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Supabase (production) — custom SMTP"
open_url "https://supabase.com/dashboard/project/${PROD_REF}/auth/smtp"
step "Enable Custom SMTP."
step "Sender email: ${BOLD}${SENDER}${RESET}   Sender name: ${BOLD}PRISM${RESET}"
step "Host: ${BOLD}smtp.resend.com${RESET}   Port: ${BOLD}465${RESET}"
step "Username: ${BOLD}resend${RESET}   Password: the re_… key from stage 2."
step "Save."
note "Then Authentication → Rate Limits: raise \"emails sent per hour\" above the default"
note "if invites go out in batches. Custom SMTP is what lifts the shared sender's cap."
pause

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Supabase (production) — paste the six templates"
open_url "https://supabase.com/dashboard/project/${PROD_REF}/auth/templates"
note "Templates live in ${TEMPLATE_DIR}. Keep every {{ .Var }} exactly as written."
paste_template "Confirm signup"        confirm-signup.html   "Confirm your PRISM account"
paste_template "Invite user"           invite.html           "Your artist page in the PRISM gallery"
paste_template "Magic Link"            magic-link.html       "Your PRISM sign-in link"
paste_template "Change Email Address"  change-email.html     "Confirm your new PRISM email"
paste_template "Reset Password"        reset-password.html   "Reset your PRISM password"
paste_template "Reauthentication"      reauthentication.html "Your PRISM verification code"

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Sandbox project"
say "The sandbox should match production, or its difference should be written down."
if confirm "Set up the sandbox the same way now (stages 3 and 4 against its project)?"; then
  ask SANDBOX_REF "Sandbox project ref (from its dashboard URL):"
  open_url "https://supabase.com/dashboard/project/${SANDBOX_REF}/auth/smtp"
  step "Same SMTP settings as stage 3. A separate Resend key named prism-supabase-auth-sandbox is tidier."
  pause
  open_url "https://supabase.com/dashboard/project/${SANDBOX_REF}/auth/templates"
  for f in confirm-signup invite magic-link change-email reset-password reauthentication; do
    copy_file "${TEMPLATE_DIR}/${f}.html" && note "${f}.html is on the clipboard."
    pause "Paste ${f}.html into its template (same subject as production), save, then Enter."
  done
else
  SKIPPED+=("Sandbox still uses Supabase's default sender and templates: note it on #341")
fi

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "Hand check"
say "From production, trigger each and check it arrives branded, from ${SENDER}, with working links:"
step "${BOLD}Invite${RESET}: gallery → Moderation queue → Artists → Add artist, with an address you own."
step "${BOLD}Password reset${RESET}: sign-in dialog → Forgot password."
step "${BOLD}Email change${RESET}: Profile → Account → Change email."
step "Open each in Gmail (web + phone), Outlook and Apple Mail, light and dark."
step "In one message's source, look for ${BOLD}spf=pass dkim=pass dmarc=pass${RESET}."
if ! confirm "All three arrived branded, from ${SENDER}, links working?"; then
  SKIPPED+=("Hand check of invite / reset / email change")
fi

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "Resend — sender passing"
open_url "https://resend.com/emails"
step "The test messages show as Delivered from ${SENDER}."
note "Once this sender and relay.${ROOT_DOMAIN} both pass, #336's DMARC tightening can go ahead."
pause

finish
say "Supabase Auth now sends from ${BOLD}${SENDER}${RESET} with the PRISM templates."
